// v24.xx, HIS ORDER 2026-10-12 (about 21:48): "improve sound generally, look for other actions that don't have distinct noises yet
// and add them". THE MISSING SOUNDS. Many moments either made no sound or borrowed one that already meant something else: a bolt of
// lightning landed with the machine alarm, the strike warning and a weather turn with the machine wind-up riser. sndC plays a sound
// of its own for each of them. Each is a short recipe (a transient, a body and a short tail, the way the guns are built) of a few
// filtered noise and tone layers, placed in the world like every other sound (distance, pan, and the wall lowpass when a wall is
// in the way) or played in your own ears for a HUD moment, on the bus for its kind, and rate limited per kind so twenty in a fight
// never smear or clip. A world sound is made by each window for itself and never passed to the party, so it is heard once in each.
// Cosmetic only: Math.random fills the noise buffers, nothing seeded is drawn, no game state changes, never under G.sim or in the
// spectating host window, never a voice and never a sustained tone.
// THE STORM. A bolt landing is thunder now: a hard 3.5 kHz crack, then a low roll of about a second and a half over a sub thump
// falling from 60 to 35 Hz, the crack fading with distance so a far bolt is all roll. The strike warning is static building over its
// 1.2 s (spikes of crackle on a rising hiss, with a thin fizz), so it leads into the crack. A weather turn is the sky it turns to: a
// storm a distant thunder roll with no crack, rain, fog or a clear sky a gust of wind, a blackout a power-down and a relay clunk.
var SNDC={n:0,last:'',lastO:null,log:[],at:{},cnt:{}};
var SNDC_R={};
function sndCNoise(a,OUT,L,vol,t){
  var n=Math.max(64,Math.floor(a.sampleRate*L.d)), b=a.createBuffer(1,n,a.sampleRate), c=b.getChannelData(0), i, x, e, sh=L.sh||'dec', sp=0, t0=t+(L.at||0), s, f, g;
  for(i=0;i<n;i++){
    x=i/n;
    if(sh==='swell') e=Math.sin(Math.PI*Math.pow(x,L.k||0.5));
    else if(sh==='rise') e=Math.pow(x,L.k||1.5)*(x>0.9?(1-x)*10:1);
    else e=Math.pow(1-x,L.pw||2);
    if(L.ch) e*=(Math.sin(6.2832*L.ch*i/a.sampleRate)>0?1:0.2);   // a chop, for a saw or drill rasp
    if(L.cr){ if(Math.random()<L.cr) sp=1; sp*=0.993; e*=0.12+sp; }   // crackle: random spikes of static
    c[i]=(Math.random()*2-1)*e;
  }
  s=a.createBufferSource(); s.buffer=b;
  f=a.createBiquadFilter(); f.type=L.ft||'lowpass'; f.Q.value=L.q||0.7;
  f.frequency.setValueAtTime(L.f0,t0); if(L.f1) f.frequency.exponentialRampToValueAtTime(L.f1,t0+L.d);
  g=a.createGain(); g.gain.value=L.g*vol;
  s.connect(f); f.connect(g); g.connect(OUT); s.start(t0);
}
function sndCTone(a,OUT,L,vol,t){
  var t0=t+(L.at||0), o=a.createOscillator(), g=a.createGain(), f;
  o.type=L.ty||'sine';
  o.frequency.setValueAtTime(L.f0,t0); if(L.f1&&L.f1!==L.f0) o.frequency.exponentialRampToValueAtTime(L.f1,t0+(L.fd||L.d));
  g.gain.setValueAtTime(0.0001,t0); g.gain.exponentialRampToValueAtTime(Math.max(0.0002,L.g*vol),t0+(L.atk||0.004)); g.gain.exponentialRampToValueAtTime(0.0001,t0+L.d);
  if(L.lp){ f=a.createBiquadFilter(); f.type='lowpass'; f.frequency.value=L.lp; f.Q.value=0.7; o.connect(f); f.connect(g); } else o.connect(g);
  g.connect(OUT); o.start(t0); o.stop(t0+L.d+0.02);
}
function sndC(kind,px,py,o){
  var R=SNDC_R[kind], a, t, w, e=null, ctx, vol=1, Ls, out, pn, lp, i, nr, hr, pos;
  if(!R||(G&&G.sim)) return false;
  if(typeof NET==='object'&&NET&&NET.specTick) return false;
  pos=(px!==undefined&&px!==null&&py!==undefined&&py!==null&&isFinite(px)&&isFinite(py));
  if(pos&&R.mark&&NOISEMARK[kind]) noiseMark(kind,px,py);   // a world sound you cannot see still leaves its ring
  a=ac(); if(!a) return false;
  t=a.currentTime; w=SNDC.at[kind];
  if(w!==undefined&&t>=w&&t-w<(R.gap||0.06)) return false;   // one at a time per kind, so a burst never smears
  if(pos){ e=earsOf(px,py); nr=R.near||300; hr=Math.max(nr+50,R.hear||900); vol=e.d<=nr?1:clamp(1-(e.d-nr)/(hr-nr),0,1); if(vol<0.03) return false; }
  Ls=(typeof R.L==='function')?R.L(o||{},e?e.d:0):R.L; if(!Ls||!Ls.length) return false;
  out=sndBus(R.bus||'world'); if(!out) return false;
  try{
    if(pos){
      ctx=sndPlace(px,py);
      if(PAN_OK&&a.createStereoPanner){ pn=a.createStereoPanner(); pn.pan.value=clamp(e.pan*(ctx.panK||1),-1,1); pn.connect(out); out=pn; }
      if(ctx.lp>0){ lp=a.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=ctx.lp; lp.Q.value=0.7; lp.connect(out); out=lp; }
    } else if(o&&typeof o.pan==='number'&&PAN_OK&&a.createStereoPanner){ pn=a.createStereoPanner(); pn.pan.value=clamp(o.pan,-1,1); pn.connect(out); out=pn; }
    for(i=0;i<Ls.length&&i<8;i++){ if(Ls[i].k==='n') sndCNoise(a,out,Ls[i],vol*(R.v||1),t); else sndCTone(a,out,Ls[i],vol*(R.v||1),t); }
  }catch(err){ return false; }
  SNDC.at[kind]=t; SNDC.n++; SNDC.last=kind; SNDC.lastO=o||null; SNDC.cnt[kind]=(SNDC.cnt[kind]||0)+1;
  SNDC.log.push(kind); if(SNDC.log.length>40) SNDC.log.shift();
  return true;
}
NOISEMARK.thunder={r:120,hear:1500};
NOISEMARK.strikewarn={r:60,hear:820};
SNDC_R.thunder={bus:'world',hear:1500,near:450,gap:0.25,mark:1,L:function(o,d){
  var ck=clamp(1-d/1100,0.12,1);
  return [{k:'n',d:0.045,pw:1.4,ft:'highpass',f0:3500,q:0.7,g:0.22*ck},
          {k:'n',d:0.1,pw:2.2,ft:'bandpass',f0:1300,q:0.8,g:0.12*ck,at:0.008},
          {k:'n',d:1.45,sh:'swell',k:0.25,ft:'lowpass',f0:420,f1:170,q:0.8,g:0.34,at:0.03},
          {k:'o',ty:'sine',f0:60,f1:35,d:0.9,g:0.24,atk:0.02,at:0.02}]; }};
SNDC_R.strikewarn={bus:'world',hear:900,near:300,gap:0.2,mark:1,L:[
  {k:'n',d:1.25,sh:'rise',k:1.6,cr:0.0025,ft:'highpass',f0:2600,q:0.7,g:0.11},
  {k:'n',d:1.2,sh:'rise',k:2,ft:'bandpass',f0:2200,f1:3000,q:5,g:0.05}]};
SNDC_R.wxturn={bus:'world',gap:0.5,L:function(o){
  if(o.sky==='storm') return [{k:'n',d:0.95,sh:'swell',k:0.5,ft:'lowpass',f0:320,f1:160,q:0.9,g:0.22},
                              {k:'n',d:0.8,sh:'swell',k:0.4,ft:'lowpass',f0:110,q:0.7,g:0.22,at:0.08}];
  if(o.sky==='blackout') return [{k:'o',ty:'square',f0:120,f1:40,d:0.55,g:0.07,atk:0.01,lp:700},
                                 {k:'n',d:0.045,pw:2,ft:'bandpass',f0:1700,q:3,g:0.16,at:0.56},
                                 {k:'o',ty:'sine',f0:95,f1:60,d:0.08,g:0.12,at:0.56}];
  return [{k:'n',d:1.05,sh:'swell',k:0.6,ft:'bandpass',f0:400,f1:1200,q:1.2,g:0.12}]; }};
// sndC recipes end// ================================================================ utils

